library(ggplot2);library(patchwork);library(grid)
make_rpe1_native<-function(C){
 D<-file.path(C,'results/plot_data');a<-read.csv(file.path(D,'syri_anchors.csv'),stringsAsFactors=FALSE);cp<-read.csv(file.path(D,'author_bezier_controls.csv'));lens<-read.csv(file.path(D,'chromosome_lengths.csv'));hor<-read.csv(file.path(D,'chm13_live_hor.csv'));chrs<-c(paste0('chr',1:22),'chrX');rank<-setNames(23:1,chrs)
 # Exact cubic controls are exported by the original plotsr1.1.1 function.
 # Sixty-four steps approximate only the renderer path; source endpoints stay exact.
 bez<-function(z,t){o<-1-t;outer(o^3,z[1,])+outer(3*o^2*t,z[2,])+outer(3*o*t^2,z[3,])+outer(t^3,z[4,])}
 tt<-seq(0,1,length.out=65);curves<-lapply(split(cp,cp$anchor_id),function(z){z<-z[order(z$vertex),];v<-as.matrix(z[,c('x','y')]);rbind(bez(v[1:4,],tt),v[5,,drop=FALSE],bez(v[5:8,],tt),v[9,,drop=FALSE])});poly<-do.call(rbind,lapply(names(curves),function(id){v<-curves[[id]];data.frame(anchor_id=id,x=v[,1],y=v[,2])}));poly<-merge(poly,a[,c('anchor_id','hap','display_type','achr')],by='anchor_id',sort=FALSE);poly$z<-poly$display_type!='SYN';poly<-poly[order(poly$z),];a$display_type<-factor(a$display_type,levels=c('SYN','INV','TRANS','DUP'))
 # Independent control identity check against the R expression of author arithmetic.
 expected<-do.call(rbind,lapply(seq_len(nrow(a)),function(i){r<-a[i,];data.frame(anchor_id=r$anchor_id,vertex=0:8,x=c(r$astart,r$astart,r$bstart,r$bstart,r$bend,r$bend,r$aend,r$aend,r$astart),y=c(r$ry,(r$ry+r$qy)/2,(r$ry+r$qy)/2,r$qy,r$qy,(r$ry+r$qy)/2,(r$ry+r$qy)/2,r$ry,r$ry))}));j<-merge(cp,expected,by=c('anchor_id','vertex'),suffixes=c('.author','.R'));stopifnot(nrow(j)==nrow(cp),max(abs(j$x.author-j$x.R))==0,max(abs(j$y.author-j$y.R))==0)
 write.csv(poly,file.path(D,'rendered_bezier_paths.csv'),row.names=FALSE);write.csv(data.frame(chr=chrs,row=unname(rank)),file.path(D,'display_chromosome_order.csv'),row.names=FALSE)
 cols<-list(SYN=linearGradient(c('#F0F3F3','#D3DDDE'),x1=.5,y1=1,x2=.5,y2=0,group=FALSE),INV=linearGradient(c('#DEC5D3','#9D577B'),x1=.5,y1=1,x2=.5,y2=0,group=FALSE),TRANS=linearGradient(c('#ADCFCA','#4E8F8A'),x1=.5,y1=1,x2=.5,y2=0,group=FALSE),DUP=linearGradient(c('#9EBCC7','#376A82'),x1=.5,y1=1,x2=.5,y2=0,group=FALSE))
 plots<-lapply('Hap1',function(h){b<-poly[poly$hap==h,];ref<-lens[lens$hap=='CHM13',];ref$y<-rank[ref$chr]+.34;qry<-lens[lens$hap==h,];qry$basechr<-sub('_hap[12]$','',qry$chr);qry$y<-rank[qry$basechr]-.34;ref<-ref[!is.na(ref$y),];qry<-qry[!is.na(qry$y),];hr<-hor;hr$y<-rank[hr$chr]+.47
  ggplot()+geom_vline(xintercept=seq(0,250,50)*1e6,color='#DCE2E4',linewidth=.15)+geom_polygon(data=b,aes(x=x,y=y,group=anchor_id,fill=display_type),color=NA)+geom_segment(data=ref,aes(x=0,xend=length_bp,y=y+.12,yend=y+.12),color='#D5DDDF',linewidth=.35)+geom_segment(data=ref,aes(x=0,xend=length_bp,y=y,yend=y),color='#548C88',linewidth=.35)+geom_segment(data=qry,aes(x=0,xend=length_bp,y=y,yend=y),color=if(h=='Hap1')'#BB8CA8'else'#7E5576',linewidth=.35)+geom_segment(data=hr,aes(x=start0,xend=end0,y=y,yend=y),linewidth=.55,color='#25363F')+scale_fill_manual(values=cols,guide='none')+scale_x_continuous(limits=c(0,250e6),breaks=c(0,50,100,150,200,250)*1e6,labels=c('0','50','100','150','200','250'),expand=c(0,0),position='top')+scale_y_continuous(breaks=unname(rank),labels=names(rank),expand=c(0,0),limits=c(.4,23.68))+labs(x='Chromosome position (Mb)',y=NULL)+theme_void(base_family='Arial',base_size=7)+theme(axis.text.x=element_text(size=6.5,color='#4B5C64',margin=margin(b=1)),axis.text.y=element_text(size=6.5,color='#34454D',margin=margin(r=2)),axis.title.x=element_text(size=7,color='#34454D',margin=margin(b=3)),plot.margin=margin(1,2,0,1))
 })
 qc<-list(status='PASS',native_controls=nrow(cp),r_native_controls=nrow(expected),maximum_control_error_bp=0,all_anchor_ids_retained=setequal(a$anchor_id,unique(poly$anchor_id)),all_23_chromosome_pairs_retained=all(vapply('Hap1',function(h)setequal(a$achr[a$hap==h],chrs),TRUE)),anchors=nrow(a),curves=length(curves),sample_points=nrow(poly),curve_sampling_steps=64,base_pair_coordinates_unchanged=TRUE)
 list(plots=plots,anchors=a,controls=cp,lengths=lens,hor=hor,qc=qc)
}
collect_grob_text<-function(g,inherited=grid::gpar()){gp<-inherited;for(k in names(g$gp))gp[[k]]<-g$gp[[k]];out<-list(labels=character(),families=character(),sizes=numeric());if(inherits(g,'text')&&length(g$label))out<-list(labels=as.character(g$label),families=gp$fontfamily,sizes=gp$fontsize);for(child in c(g$grobs,as.list(g$children))){x<-collect_grob_text(child,gp);for(k in names(out))out[[k]]<-c(out[[k]],x[[k]])};out}
font_grob<-function(g){if(is.null(g$gp))g$gp<-gpar();g$gp$fontfamily<-'Arial';if(length(g$grobs))g$grobs<-lapply(g$grobs,font_grob);if(length(g$children))g$children<-do.call(gList,lapply(as.list(g$children),font_grob));g}
make_rpe1_hap1<-function(C){p<-make_rpe1_native(C);base<-p$plots[[1]];chrs<-c(paste0('chr',1:22),'chrX');rank<-setNames(23:1,chrs);zooms<-lapply(c('chr1','chr9'),function(chr){z<-unserialize(serialize(base,NULL));for(i in 2:6){d<-z$layers[[i]]$data;key<-if('achr'%in%names(d))'achr'else if('basechr'%in%names(d))'basechr'else'chr';d<-d[d[[key]]==chr,];d$y<-d$y-rank[[chr]];z$layers[[i]]$data<-d};z+scale_x_continuous(breaks=if(chr=='chr1')c(100,120,140,160)*1e6 else c(30,50,70,90)*1e6,labels=if(chr=='chr1')c('100','120','140','160')else c('30','50','70','90'),expand=c(0,0))+scale_y_continuous(breaks=c(-.34,.34),labels=c('Hap1','CHM13'),limits=c(-.53,.6),expand=c(0,0))+coord_cartesian(xlim=if(chr=='chr1')c(100,160)*1e6 else c(30,90)*1e6)+labs(x='Chromosome position (Mb)')+theme(axis.title.x=element_text(size=7,margin=margin(t=3)),plot.margin=margin(1,2,1,1))});p$plots<-c(list(base),zooms);p}
make_native_grobs<-function(p)lapply(p$plots,function(x)font_grob(ggplotGrob(x)))
draw_native<-function(gs){grid.newpage();titles<-c('a  CHM13 vs. RPE-1 Hap1','b  Chromosome 1','c  Chromosome 9');for(i in 1:3)grid.text(titles[i],x=unit(c(2,96,96)[i],'mm'),y=unit(c(163,150,80)[i],'mm'),just=c('left','top'),gp=gpar(fontfamily='Arial',fontsize=8,fontface='bold',col='#253B44'))
 boxes<-data.frame(id=c('a','b','c'),x=c(1,94,94),y=c(12,91,20),w=c(88.5,87.5,87.5),h=c(146,54,54));metrics<-list();for(i in 1:3){b<-boxes[i,];pushViewport(viewport(x=unit(b$x,'mm'),y=unit(b$y,'mm'),width=unit(b$w,'mm'),height=unit(b$h,'mm'),just=c('left','bottom')));grid.draw(gs[[i]]);grid.force();lo<-deviceLoc(unit(0,'npc'),unit(0,'npc'),valueOnly=TRUE);hi<-deviceLoc(unit(1,'npc'),unit(1,'npc'),valueOnly=TRUE);metrics[[i]]<-list(id=b$id,x=lo$x*25.4,y=lo$y*25.4,w=(hi$x-lo$x)*25.4,h=(hi$y-lo$y)*25.4);popViewport()}
 labs<-c('CHM13','Hap1','Synteny','Inversion','Translocation','Duplication','Live HOR');cols<-c('#548C88','#BB8CA8','#D3DDDE','#9D577B','#4E8F8A','#376A82','#25363F');for(i in seq_along(labs)){x<-c(3,29,49,74,101,136,165)[i];grid.rect(x=unit(x,'mm'),y=unit(5,'mm'),width=unit(2,'mm'),height=unit(.85,'mm'),just='left',gp=gpar(col=NA,fill=cols[i]));grid.text(labs[i],x=unit(x+3,'mm'),y=unit(5,'mm'),just='left',gp=gpar(fontfamily='Arial',fontsize=6.5,col='#34454D'))}
 texts<-lapply(gs,collect_grob_text);list(boxes=metrics,text=unique(c(titles,labs,unlist(lapply(texts,`[[`,'labels')))),families=unique(c('Arial',unlist(lapply(texts,`[[`,'families')))),sizes=unique(c(8,6.5,unlist(lapply(texts,`[[`,'sizes')))))
}
